def reg2bin(beg,end):
    end=max(beg+1,end)-1
    if beg>>14==end>>14:return 4681+(beg>>14)
    if beg>>17==end>>17:return 585+(beg>>17)
    if beg>>20==end>>20:return 73+(beg>>20)
    if beg>>23==end>>23:return 9+(beg>>23)
    if beg>>26==end>>26:return 1+(beg>>26)
    return 0


def encode_tags(tags):
    out=bytearray()
    for t in tags:
        if len(t)<5:continue
        key,typ,v=t.split(':',2)
        try:
            if typ in 'cCsSiI':
                n=int(v)
                if n>=0:
                    typ,fmtc=('C','B') if n<256 else ('S','H') if n<65536 else ('I','I')
                else:typ,fmtc=('c','b') if n>=-128 else ('s','h') if n>=-32768 else ('i','i')
                val=struct.pack('<'+fmtc,n)
            elif typ in 'fd':val=struct.pack('<'+typ,float(v))
            elif typ=='A':val=v[:1].encode()
            elif typ=='B':
                items=v.split(',');sub=items[0];vals=items[1:];f={'c':'b','C':'B','s':'h','S':'H','i':'i','I':'I','f':'f','d':'d'}[sub]
                val=sub.encode()+struct.pack('<i',len(vals))+b''.join(struct.pack('<'+f,float(x) if sub in 'fd' else int(x)) for x in vals)
            else:val=v.encode()+b'\0'
            out.extend(key.encode()[:2]+typ.encode()+val)
        except (ValueError,struct.error,KeyError):continue
    return bytes(out)


def bam_header(a):
    t=a.header_text().encode();out=b'BAM\x01'+struct.pack('<i',len(t))+t+struct.pack('<i',len(a.refs))
    for name,ln in a.refs:
        n=name.encode()+b'\0';out+=struct.pack('<i',len(n))+n+struct.pack('<i',ln)
    return out


def bam_record(r,refs):
    rid=refs.get(r.ref,-1);nrid=refs.get(r.mate_ref(),-1);pos=r.pos-1;npos=r.mpos-1
    name=r.name.encode()+b'\0';ops=r.ops();ls=r.qlen()
    bin=reg2bin(pos,pos+max(1,r.reflen())) if pos>=0 else 4680
    out=struct.pack('<iiIIiiii',rid,pos,(bin<<16)|(r.mapq<<8)|len(name),(r.flag<<16)|len(ops),ls,nrid,npos,r.tlen)+name
    out+=b''.join(struct.pack('<I',(n<<4)|CIGAR_CODES.index(c)) for n,c in ops)
    seq=r.seq if ls else '';sb=bytearray()
    for i in range(0,ls,2):sb.append((BASE_MAP.get(seq[i],15)<<4)|(BASE_MAP.get(seq[i+1],15) if i+1<ls else 0))
    out+=sb
