        if len(t)<5:continue
        key,typ,v=t.split(':',2)
        try:
            if typ in 'cCsSiI':
                n=int(v)
                if n>=0:
                    typ,fmtc=('C','B') if n<256 else ('S','H') if n<65536 else ('I','I')
                else:typ,fmtc=('c','b') if n>=-128 else ('s','h') if n>=-32768 else ('i','i')
