def output_format(o,path=None,default='sam'):
    if o.has('O'):return o.get('O').split(',')[0].lower()
    if o.has('C'):return 'cram'
    if o.has('b') or o.has('u') or o.has('1'):return 'bam'
    if path and path.endswith(('.bam','.ubam')):return 'bam'
    if path and path.endswith('.cram'):return 'cram'
    if path and path.endswith(('.sam','.sam.gz')):return 'sam'
