    if a.bad:
        c=common.COMMAND
        if c=='view':fail(f'samtools view: error reading file "{a.path}"')
        if c=='flagstat':fail('samtools flagstat: error reading from input file')
        if c=='sort':fail(f'samtools sort: truncated file. Aborting')
        fail(f'samtools {c}: error reading file "{a.path}"')


def has_index(path):
    paths=[path+'.bai',path+'.csi',path+'.crai',os.path.splitext(path)[0]+'.bai',os.path.splitext(path)[0]+'.csi']
    return any(os.path.exists(p) for p in paths)


def need_index(a,kind=None):
    if has_index(a.path):return
