    d={x[0]:x for x in seqs}
    if reg in d:return d[reg],0,len(d[reg][1]),None
    m=re.match(r'^(.*):([\d,]*)(?:-([\d,]*))?$',reg)
    if m and m[1] in d:
        start=int((m[2] or '1').replace(',',''))-1
