# Walk a CIGAR into reference coordinates.  Insertions are attached to the
# preceding reference base, while D and N each retain their occupied span.
def walk(r):
    p=r.pos-1;q=0;qual=r.quals();seq='' if r.seq=='*' else r.seq
    events=[]
    for n,c in r.ops():
        if c in 'M=X':
            for i in range(n):
                events.append({'p':p,'q':q,'c':c,'b':seq[q] if q<len(seq) else 'N','qual':qual[q] if q<len(qual) else 255,'indels':[]})
                p+=1;q+=1
        elif c=='I':
            if events:events[-1]['indels'].append(('+',n,seq[q:q+n]))
            q+=n
        elif c in 'DN':
            if c=='D' and events:events[-1]['indels'].append(('-',n,p))
            for i in range(n):
                events.append({'p':p,'q':q,'c':c,'b':'*' if c=='D' else '>', 'qual':qual[q] if q<len(qual) else (qual[-1] if qual else 255),'indels':[]})
                p+=1
        elif c=='S':q+=n
        elif c=='B':q=max(0,q-n)
    if events:events[0]['first']=True;events[-1]['last']=True
    return events


