from alignment import *
import common

MOD=(1<<31)-1


def checksum(args):
    long={'exclude-flags=':'F','require-flags=':'f','flag-mask=':'b','no-rev-comp':'c','tags=':'t','in-order':'O','check-pos':'P','check-cigar':'C','check_mate':'M','sanitize=':'z','count=':'N','output=':'o','show-qc':'q','verbose':'v','all':'a','tabs':'T','merge=':'m','bamseqchksum':'B'}
    o=Options(args,'F:f:b:ct:OPCMz:N:o:qvaTm:B@:',long)
    files=o.pos or ['-'];out=[]
    if o.has('a'):
        for k in ['P','C','M','O','c']:o.values[k]=[True]
        o.values['b']=['4095'];o.values['F']=['0'];o.values['f']=['0'];o.values['t']=['*,cF,MD,NM']
    mask=parse_flags(str(o.get('b','193')));exc=parse_flags(str(o.get('F','2304')));req=parse_flags(str(o.get('f','0')))
    tags=sorted(set(o.get('t','BC,FI,QT,RT,TC').split(',')))
    if o.has('a'):tags=['*','cF','MD','NM']
    if o.has('m'):return 0
    for path in files:
        a=read_alignment(path);check_read(a);refmap={n:i for i,(n,l) in enumerate(a.refs)}
        groups=OrderedDict();groups['all']={};groups['-']={}
        keys=['flag+seq','+name','+qual','+aux']+(['+chr/pos'] if o.has('P') else [])+(['+cigar'] if o.has('C') else [])+(['+mate'] if o.has('M') else [])
        nc=len(keys)
        def group(name,q):
            if name not in groups:groups[name]={}
            if q not in groups[name]:groups[name][q]=[0]+[1]*(nc+1)
            return groups[name][q]
        for name in ['all','-']:
            for qc in ['all','pass','fail']:group(name,qc)
        processed=0
        for r in a.records:
            if r.flag&exc or r.flag&req!=req:continue
            if o.num('N') and processed>=o.num('N'):break
            seq=r.seq if r.seq!='*' else '';qual=r.qual
            if qual=='*':qual=chr(32)*len(seq)
            if r.flag&16 and not o.has('c'):seq=revcomp(seq);qual=qual[::-1]
            fs=bytes([r.flag&mask&255])+seq.encode()
            crc=zlib.crc32(fs)
            crcs=[crc,zlib.crc32(r.name.encode()+b'\0'+fs),zlib.crc32(qual.encode(),crc)]
            chosen=[t for t in r.tags if '*' in tags or t[:2] in tags]
            if o.has('a'):chosen=[t for t in chosen if t[:2] not in ('MD','NM','cF')]
            chosen.sort(key=lambda t:t[:2]);crcs.append(zlib.crc32(encode_tags(chosen),crc))
            if o.has('P'):crcs.append(zlib.crc32(struct.pack('<iq',refmap.get(r.ref,-1),r.pos-1),crc))
            if o.has('C'):crcs.append(zlib.crc32(struct.pack('<i',r.mapq)+b''.join(struct.pack('<I',(n<<4)|CIGAR_CODES.index(c)) for n,c in r.ops()),crc))
            if o.has('M'):crcs.append(zlib.crc32(struct.pack('<iq',refmap.get(r.mate_ref(),-1) if r.mpos else -1,r.mpos-1),crc))
            if o.has('O'):
                ordcrc=zlib.crc32(struct.pack('<Q',processed))
                crcs=[v^ordcrc for v in crcs]
            vals=[(x&MOD) or 1 for x in crcs]
            combined=vals[0]*vals[0]*vals[1]*vals[3]%MOD
            for v in vals[4:]:combined=combined*v%MOD
            vals.append(combined)
            for name in ['all',str(r.gettag('RG','-'))]:
                for qc in ['all','fail' if r.flag&512 else 'pass']:
                    data=group(name,qc);data[0]+=1
                    for i,v in enumerate(vals,1):data[i]=data[i]*v%MOD
            processed+=1
        tab=o.has('T');bam=o.has('B')
        if bam:out.append('###\tset\tcount\t\tb_seq\tname_b_seq\tb_seq_qual\tb_seq_tags('+','.join(tags)+')\n')
        elif tab:
            out.extend(['# Checksum 1.0 for file:\t'+path+'\n','# Aux tags:\t'+','.join(tags)+'\n','# BAM flags:\t'+flag_str(mask)+'\n\n','# Group\tQC\tcount\t'+'\t'.join(keys+['combined'])+'\n'])
        else:
            out.extend(['# Checksum 1.0 for file: '+path+'\n','# Aux tags:          '+','.join(tags)+'\n','# BAM flags:         '+flag_str(mask)+'\n\n','# Group    QC          count  '+'  '.join([f'{key:<7}' for key in keys]+['combined']).rstrip()+'\n'])
        for name,g in groups.items():
            for qc in (['all','pass','fail'] if o.has('q') or bam else ['all']):
                data=g.get(qc,[0]+[1]*(nc+1))
                if not data[0] and not o.has('v'):continue
                if bam:out.append(('' if name=='-' else name)+'\t'+qc+'\t'+str(data[0])+'\t\t'+'\t'.join(format(v,'x') for v in data[1:5])+'\n')
                elif tab:out.append(name+'\t'+qc+'\t'+str(data[0])+'\t'+'\t'.join(format(v,'x') for v in data[1:])+'\n')
                else:out.append(f'{name:<10} {qc:<4} {data[0]:12d}  '+'  '.join(f'{v:08x}' for v in data[1:])+'\n')
    write_output(''.join(out),o.get('o'));return 0
